using System;
using Astrea.BattleActions;

namespace Astrea;

[Serializable]
public class DiceFace : ActionFace
{
	[NonSerialized]
	public bool Timeless;

	public DiceFace(DiceFace diceFace)
	{
		FaceName = diceFace.FaceName;
		ActionValue = diceFace.ActionValue;
		base.ActionValueModifier = diceFace.ActionValueModifier;
		NewActionValue = diceFace.NewActionValue;
		if (diceFace.BattleAction != null)
		{
			BattleAction = diceFace.BattleAction;
			NewBattleAction = diceFace.NewBattleAction;
		}
		if (diceFace.EnableSecondAction)
		{
			EnableSecondAction = true;
			SecondActionValue = diceFace.SecondActionValue;
			base.SecondActionValueModifier = diceFace.SecondActionValueModifier;
			NewSecondActionValue = diceFace.NewSecondActionValue;
			if (diceFace.SecondBattleAction != null)
			{
				SecondBattleAction = diceFace.SecondBattleAction;
				NewSecondBattleAction = diceFace.NewSecondBattleAction;
			}
		}
		KeepChanges = diceFace.KeepChanges;
		KeepChangesForBattle = diceFace.KeepChangesForBattle;
		Timeless = diceFace.Timeless;
	}

	public DiceFace(string FaceName, int ActionValue, BattleAction BattleAction)
	{
		base.FaceName = FaceName;
		base.ActionValue = ActionValue;
		if (BattleAction != null)
		{
			base.BattleAction = BattleAction;
		}
	}

	public DiceFace(string FaceName, int ActionValue, BattleAction BattleAction, int SecondActionValue, BattleAction SecondBattleAction)
	{
		base.FaceName = FaceName;
		base.ActionValue = ActionValue;
		if (BattleAction != null)
		{
			base.BattleAction = BattleAction;
		}
		EnableSecondAction = true;
		base.SecondActionValue = SecondActionValue;
		if (SecondBattleAction != null)
		{
			base.SecondBattleAction = SecondBattleAction;
		}
	}
}
